import React from 'react';
import { ComboBox } from 'carbon-components-react';

const items = [
  'Option 1',
  'Option 2',
  'Option 3',
  'Option 4',
];

function App() {
  return (
    <div>
      <ComboBox
        id="carbon-combobox-example"
        items={items}
        itemToString={(item) => (item ? item : '')}
        placeholder="Filter..."
        aria-label="Combobox title"
      />
    </div>
  );
}

export default App;
